import{_ as t,o,c as a,a3 as r}from"./chunks/framework.C_Jzb_RY.js";const f=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"reference/faq.md","filePath":"reference/faq.md","lastUpdated":1794401237000}'),n={name:"reference/faq.md"};function s(d,e,i,c,h,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Questions people ask before and while using ktor-svelte.</p><p><strong>Why <code>adapter-static</code> and no server-side rendering?</strong> ktor-svelte exists to ship one JVM app. SSR needs a JavaScript runtime that renders every request, so production would need Node next to the JVM, or a JavaScript engine inside it. That means two processes or a slow embedded engine, two places for auth and config, and two things to deploy and monitor. With <code>adapter-static</code>, the frontend is plain files, Ktor is the only backend, and the JAR is the whole app.</p><p><strong>What about SEO and the first paint?</strong> Prerender every page whose content is known at build time with <code>export const prerender = true</code>. Those pages are real HTML that search engines and slow devices see right away. Pages that depend on data from your API render in the browser, which suits dashboards, admin areas and anything behind a login.</p><p><strong>How do I load data for a page?</strong> Call your Ktor routes from <code>load</code> in <code>+page.ts</code> or from the component, through the generated client. <code>+page.server.ts</code> and <code>+server.ts</code> need a Node server and do not exist here. Write that logic as a Ktor route instead.</p><p><strong>What replaces form actions?</strong> A Ktor route that receives the form as JSON or form data. Validation errors come back as a 422 that <code>isValidationError</code> understands, so the form can show them next to each field.</p><p><strong>Can I still add SSR later?</strong> Yes, but not with ktor-svelte. Switch the frontend to <code>adapter-node</code>, run it as its own server, and keep Ktor as the API behind it. You lose the single JAR and the same-origin setup, and you need CORS or a proxy.</p><p><strong>Does a dynamic route like <code>/notes/[id]</code> work?</strong> Yes. Unknown paths get the fallback page, and SvelteKit renders the route in the browser. List patterns in <code>paramRoutes</code> to serve the fallback for them even when a request does not accept HTML.</p>',8)])])}const g=t(n,[["render",s]]);export{f as __pageData,g as default};
